def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(v for row in grid for v in row)
    background = counts.most_common(1)[0][0]
    foreground = max((v for v in counts if v != background), key=lambda v: counts[v])
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == foreground]
    r0, r1 = min(r for r, c in points), max(r for r, c in points)
    c0, c1 = min(c for r, c in points), max(c for r, c in points)
    out = [row[:] for row in grid]
    # Complete top and bottom horizontal boundaries of the foreground bounds.
    for r in (r0, r1):
        for c in range(c0, c1 + 1):
            if grid[r][c] == background:
                out[r][c] = 2
    # Bridge interior horizontal rows with at least three foreground marks.
    for r in range(r0 + 1, r1):
        cols = [c for c in range(c0, c1 + 1) if grid[r][c] == foreground]
        if len(cols) >= 3:
            for a, b in zip(cols, cols[1:]):
                for c in range(a + 1, b):
                    if grid[r][c] == background:
                        out[r][c] = 2
    # Complete gaps along each vertical line containing multiple marks.
    for c in range(c0, c1 + 1):
        rows = [r for r in range(r0, r1 + 1) if grid[r][c] == foreground]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == background:
                    out[r][c] = 2
    return out
